//--- Pueblos que civ_people acaba de llenar: decide (una vez por llenado) cuantos de sus civiles son durmientes
VIOC_IW_fnc_sleeperSpawn = {
	if ((VIOC_IW_SLEEP_LVL <= 0) || {isNil "VIOC_CIVP_ACTIVE"}) exitWith {};
	private _tot = VIOC_IW_SL_TOTAL select VIOC_IW_SLEEP_LVL;
	private _alive = {alive _x} count VIOC_IW_SLEEPERS;
	if (_alive >= _tot) exitWith {};
	private _perT = VIOC_IW_SL_TOWN select VIOC_IW_SLEEP_LVL;
	private _ratio = VIOC_IW_SL_RATIO select VIOC_IW_SLEEP_LVL;
	private _pls = call VIOC_IW_fnc_players;
	{
		private _town = _x;
		if (!isNull _town && {_alive < _tot}) then {
			private _since = _town getVariable ["vioc_civp_since", -1];
			if ((_town getVariable ["vioc_iw_fill", -2]) != _since) then {
				_town setVariable ["vioc_iw_fill", _since];
				private _side = [_town] call VIOC_IW_fnc_townInsSide;
				if ((_side in VIOC_IW_INS) && {[2] call VIOC_IW_fnc_room}) then {
					private _civs = (_town getVariable ["vioc_civp_units", []]) select {alive _x};
					private _h = [_town] call VIOC_IW_fnc_host;
					private _r = (_ratio + 0.06 * _h) min 0.4;
					private _cap = (_perT + ([0, 1] select (_h >= 1))) min 3;
					private _n = ((({(random 1) < _r} count _civs) min _cap) min (_tot - _alive));
					(_town getVariable ["vioc_civp_cache", [[], []]]) params [["_in", []], ["_out", []]];
					private _spots = if (count _out > 0) then {_out} else {_in};
					for "_k" from 1 to _n do {
						private _pos = [];
						for "_t" from 1 to 8 do {
							if (count _pos == 0 && {count _spots > 0}) then {
								private _p = selectRandom _spots;
								if (!([_p, 250, _pls] call VIOC_IW_fnc_seen) && {(_pls findIf {(_x distance2D _p) < 40}) < 0}) then {_pos = _p};
							};
						};
						if ((count _pos > 1) && {[1] call VIOC_IW_fnc_room}) then {
							private _hawk = (random 1) < VIOC_IW_HAWK_SHARE;
							private _u = [call VIOC_IW_fnc_civClass, _pos, _side, ["sleeper", "hawk"] select _hawk, _town] call VIOC_IW_fnc_mkCovert;
							if (!isNull _u) then {
								isNil {VIOC_IW_SLEEPERS pushBack _u};
								[1] call VIOC_IW_fnc_reserve;
								_alive = _alive + 1;
								[0] call VIOC_IW_fnc_stat;
								[format ["%1 de %2 en %3 (hostilidad %4)", ["durmiente", "halcon"] select _hawk, _side, _town getVariable ["cti_town_name", "?"], (round (_h * 100)) / 100]] call VIOC_IW_fnc_log;
							};
						};
					};
				};
			};
		};
	} forEach ((missionNamespace getVariable ["VIOC_CIVP_ACTIVE", []]) + []);
};

