			[_t, _u getVariable ["vioc_iw_side", resistance], _u] call VIOC_IW_fnc_tipOff;
		};
	};
};

//--- [unidad]: una pasada de un durmiente o halcon vivo
VIOC_IW_fnc_sleeperTick = {
	params ["_u"];
	if (!alive _u) exitWith {};
	private _town = _u getVariable ["vioc_iw_town", objNull];
	private _rev = _u getVariable ["vioc_iw_revealed", -1];
	private _hid = _rev < 0;
	//--- limpieza: oculto, con los civiles de su pueblo (o lejos de jugadores); revelado, lejos de jugadores (15 min: 300 m)
	private _gone = if (_hid) then {
		(isNull _town || {!(_town in (missionNamespace getVariable ["VIOC_CIVP_ACTIVE", []]))} || {(_u distance2D _town) > 700}) && {[_u, 500] call VIOC_IW_fnc_canDel}
	} else {
		[_u, [VIOC_IW_DEL_R, 300] select ((time - _rev) > 900)] call VIOC_IW_fnc_canDel
	};
	if (_gone) exitWith {deleteVehicle _u};
	if (_hid) then {
		if (isNil {_u getVariable "vioc_iw_fled"}) then {
			if ((_u getVariable ["vioc_iw_kind", ""]) == "hawk") then {[_u, _town] call VIOC_IW_fnc_hawkTick} else {[_u, _town] call VIOC_IW_fnc_lurkTick};
		};
	} else {
		//--- despues del ataque, la mitad huye y la otra mitad pelea hasta el final
		if (isNil {_u getVariable "vioc_iw_fled"} && {time > (_u getVariable ["vioc_iw_strikeT", 0])}) then {
			private _t = _u getVariable ["vioc_iw_tgt", objNull];
