};

//--- [objetivo, bando insurgente, halcon] -> grupos avisados: revela el grupo del objetivo a los grupos insurgentes a
//--- <= 1.5 km (los del bando del halcon si hay; si no, los de cualquier bando insurgente) y, con ai_tactics, manda hacia
//--- el a una guarnicion insurgente libre
VIOC_IW_fnc_tipOff = {
	params ["_t", "_side", ["_from", objNull]];
	if (isNull _t || {!alive _t}) exitWith {0};
	private _tp = getPosATL _t;
	private _tus = (units group _t) select {alive _x && {(_x distance2D _tp) < 300}};
	if !(isNull objectParent _t) then {_tus pushBackUnique (vehicle _t)};
	private _gs = allGroups select {((side _x) in VIOC_IW_INS) && {!isNull (leader _x)} && {alive (leader _x)} && {!isPlayer (leader _x)}};
	//--- primero los de su bando (en la mision B la narcoinsurgencia y la guerrilla tambien pelean entre si)
	private _own = _gs select {((side _x) isEqualTo _side) && {((leader _x) distance2D _tp) < VIOC_IW_TIP_R}};
	if (count _own > 0) then {_gs = _gs select {(side _x) isEqualTo _side}};
	private _keys = [];
	{
		private _d = (leader _x) distance2D _tp;
		if (_d < VIOC_IW_TIP_R) then {_keys pushBack [_d, _forEachIndex]};
	} forEach _gs;
	_keys sort true;
	private _n = 0;
	{
		private _g = _gs select (_x select 1);
		{ _g reveal [_x, 2.5] } forEach _tus;
		_n = _n + 1;
	} forEach (_keys select [0, VIOC_IW_TIP_GROUPS]);
	[2] call VIOC_IW_fnc_stat;
	if (!isNil "VIOC_TAC_RUNNING" && {count VIOC_IW_HUNT < VIOC_IW_HUNT_MAX}) then {
		private _cand = grpNull;
		{
			private _g = _gs select (_x select 1);
			if (isNull _cand && {[_g] call VIOC_IW_fnc_huntOk}) then {_cand = _g};
		} forEach _keys;
		if (!isNull _cand) then {[_cand, _t] call VIOC_IW_fnc_huntStart};
	};
	[format ["halcon en %1 avisa de %2 a %3 grupos", mapGridPosition _from, name _t, _n]] call VIOC_IW_fnc_log;
	_n
};

