//--- [civil, jugador]: pierde el dinero (como mucho lo que tiene) y el pueblo mas cercano se vuelve hostil
VIOC_IW_fnc_penalty = {
	params ["_u", "_pl"];
	private _grp = group _pl;
	private _side = side _grp;
	private _take = 0;
	isNil {
		private _f = [_grp, _side] call CTI_CO_FNC_GetFunds;
		if !(_f isEqualType 0) then {_f = 0};
		_take = VIOC_IW_PENALTY min (floor (_f max 0));
		if (_take > 0) then {[_grp, _side, -_take] call CTI_CO_FNC_ChangeFunds};
	};
	private _town = [getPosATL _u, 1500] call VIOC_IW_fnc_nearTown;
	if (!isNull _town) then {[_town, 1] call VIOC_IW_fnc_addHost};
	private _tn = if (isNull _town) then {""} else {format [" %1 se vuelve hostil.", _town getVariable ["cti_town_name", "El pueblo"]]};
	[format ["Mataste a un civil desarmado: -%1 $.%2", _take, _tn], _pl] call VIOC_IW_fnc_say;
	[10] call VIOC_IW_fnc_stat;
	[format ["civil muerto por %1: -%2 de fondos; hostil %3", name _pl, _take, if (isNull _town) then {"-"} else {_town getVariable ["cti_town_name", "?"]}]] call VIOC_IW_fnc_log;
};

//--- EntityKilled (mision) y Killed (civiles de civ_people y encubiertos): una sola vez por muerto
VIOC_IW_fnc_onKilled = {
	params ["_u", ["_k", objNull], ["_i", objNull]];
	if (isNull _u || {!(_u isKindOf "CAManBase")} || {isPlayer _u}) exitWith {};
	if (_u getVariable ["vioc_iw_dead", false]) exitWith {};
	private _cv = _u getVariable ["vioc_iw_covert", false];
	//--- el cuerpo de un insurgente nuestro (encubierto o descubierto) se borra lejos de los jugadores
	if (_cv && {!(_u getVariable ["vioc_iw_body", false])}) then {
		_u setVariable ["vioc_iw_body", true];
		[[_u], 300] spawn VIOC_IW_fnc_retire;
	};
	private _covert = _cv && {(_u getVariable ["vioc_iw_revealed", -1]) < 0};
	private _civ = !_cv && {(!isNil {_u getVariable "vioc_civp_town"}) || {(side (group _u)) isEqualTo civilian}};
	if (!_covert && {!_civ}) exitWith {};
	_u setVariable ["vioc_iw_dead", true];
	[_k, _i] call VIOC_IW_fnc_fixRating;
	private _pl = [_k, _i] call VIOC_IW_fnc_culprit;
	if (isNull _pl) exitWith {};
	if (_covert) exitWith {
		["Era un insurgente encubierto.", _pl] call VIOC_IW_fnc_say;
		[11] call VIOC_IW_fnc_stat;
	};
	if (VIOC_IW_PENALTY <= 0) exitWith {};
	[_u, _pl] call VIOC_IW_fnc_penalty;
};

//--- cada 30 s: evento Killed tambien en los civiles de civ_people (ademas de EntityKilled)
VIOC_IW_fnc_civScan = {
	{
		{
			if (!isNull _x && {alive _x} && {isNil {_x getVariable "vioc_iw_eh"}}) then {
