//=====================================================================================================================
// IED
//=====================================================================================================================
//--- -> [lugar, rumbo del camino] en un tramo de carretera usado por el gobierno, o []
VIOC_IW_fnc_iedSite = {
	private _pls = (call VIOC_IW_fnc_players) select {((getPosATL (vehicle _x)) select 2) < 150};
	if (count _pls == 0) exitWith {[]};
	private _gt = CTI_Towns select {(_x getVariable ["cti_town_sideID", -1]) in VIOC_IW_GOV_IDS};
	private _segs = [];
	private _wts = [];
	private _nearPl = {params ["_p"]; (_pls findIf {(_x distance2D _p) < 3500}) >= 0};
	//--- 1) entre pueblos del gobierno
	{
		private _a = _x;
		if ([_a] call _nearPl) then {
			{
				private _dd = _x distance2D _a;
				if ((_dd > 500) && {_dd < 3000}) then {_segs pushBack [getPosATL _a, getPosATL _x]; _wts pushBack 1};
			} forEach _gt;
		};
	} forEach _gt;
	//--- 2) escuadras del gobierno camino de su objetivo (pueblos que atacan, ordenes de movimiento)
	{
		{
			private _l = leader _x;
			if (!isNull _l && {alive _l}) then {
				private _lp = getPosATL (vehicle _l);
				private _dst = [_x] call VIOC_IW_fnc_orderDst;
				if ((count _dst > 1) && {(_lp distance2D _dst) > 600} && {[_lp] call _nearPl}) then {_segs pushBack [_lp, _dst]; _wts pushBack 2};
			};
		} forEach ((_x) call CTI_CO_FNC_GetSideGroups);
	} forEach (VIOC_IW_GOV select {_x in [west, east]});
	//--- 3) transportes de ai_transport del gobierno
	if (!isNil "VIOC_AT_LIST" && {VIOC_AT_LIST isEqualType []}) then {
		{
			if ((_x isEqualType []) && {count _x >= 5}) then {
				_x params ["_v", "", "_team", "", "_sd"];
				if ((_v isEqualType objNull) && {!isNull _v} && {alive _v} && {_sd in VIOC_IW_GOV} && {_team isEqualType grpNull} && {!isNull _team}) then {
					private _vp = getPosATL _v;
					private _dst = [_team] call VIOC_IW_fnc_orderDst;
					if ((count _dst > 1) && {(_vp distance2D _dst) > 600} && {[_vp] call _nearPl}) then {_segs pushBack [_vp, _dst]; _wts pushBack 3};
				};
			};
		} forEach VIOC_AT_LIST;
	};
	//--- 4) pueblos hostiles: hacia el pueblo del gobierno mas cercano
	{
		private _tw = _x;
		private _h = [_tw] call VIOC_IW_fnc_host;
		if ((_h > 0.2) && {[_tw] call _nearPl}) then {
			private _best = objNull;
			private _bd = 3000;
			{ private _dd = _x distance2D _tw; if ((_dd > 400) && {_dd < _bd}) then {_bd = _dd; _best = _x} } forEach _gt;
			if (!isNull _best) then {_segs pushBack [getPosATL _tw, getPosATL _best]; _wts pushBack (1 + 2 * _h)};
		};
	} forEach VIOC_IW_HOSTILE;
	if (count _segs == 0) exitWith {[]};
	private _flat = [];
	{ _flat pushBack _forEachIndex; _flat pushBack (_wts select _forEachIndex) } forEach _segs;
	private _res = [];
	for "_try" from 1 to 8 do {
		if (count _res == 0) then {
			(_segs select (selectRandomWeighted _flat)) params ["_a", "_b"];
			private _p = _a vectorAdd ((_b vectorDiff _a) vectorMultiply (0.2 + random 0.6));
			private _r = [[_p select 0, _p select 1, 0], 200] call VIOC_IW_fnc_roadAt;
			if (count _r > 0) then {
				_r params ["_rp", "_dir", "_wd"];
				private _dp = selectMin (_pls apply {_x distance2D _rp});
				if ((_dp > VIOC_IW_IED_PMIN) && {_dp < VIOC_IW_IED_PMAX}
					&& {([_rp] call VIOC_IW_fnc_baseDist) > VIOC_IW_IED_BASE}
					&& {(VIOC_IW_IEDS findIf {((_x get "site") distance2D _rp) < VIOC_IW_IED_SEP}) < 0}
					&& {(CTI_Towns findIf {(_x distance2D _rp) < 120}) < 0}) then {
					private _s = _rp getPos [(((_wd / 2) - 0.5) max 1), _dir + (selectRandom [90, -90])];
					if !(surfaceIsWater _s) then {_res = [[_s select 0, _s select 1, 0], _dir]};
				};
			};
		};
	};
	_res
};

//--- [lugar, rumbo, plantador] -> punto del detonador a 100-200 m con linea de vista al IED (y cobertura si se puede)
VIOC_IW_fnc_detSpot = {
	params ["_site", "_dir", "_u"];
	private _b = (AGLToASL _site) vectorAdd [0, 0, 0.6];
	private _pls = call VIOC_IW_fnc_players;
	private _best = [];
	private _bs = -1e9;
	for "_i" from 1 to 14 do {
		private _q = _site getPos [100 + random 100, _dir + (selectRandom [90, -90]) + (random 70) - 35];
		_q = [_q select 0, _q select 1, 0];
		if (!(surfaceIsWater _q) && {!(isOnRoad _q)}) then {
			private _a = (AGLToASL _q) vectorAdd [0, 0, 1];
			if (!(terrainIntersectASL [_a, _b]) && {(lineIntersectsSurfaces [_a, _b, _u, objNull, true, 1, "VIEW", "GEOM"]) isEqualTo []}) then {
				private _s = ([_q] call VIOC_IW_fnc_cover) - ([0, 100] select ((_pls findIf {(_x distance2D _q) < 150}) >= 0));
				if (_s > _bs) then {_bs = _s; _best = _q};
			};
		};
	};
	if (count _best == 0) then {
		_best = _site getPos [110, _dir + 90];
		_best = [_best select 0, _best select 1, 0];
	};
	_best
};

//--- [lugar, rumbo, bando, prueba, con emboscada] -> entrada (hashmap); lanza el plantador
VIOC_IW_fnc_iedLaunch = {
	params ["_site", "_dir", "_side", ["_test", false], ["_amb", false]];
	private _e = createHashMapFromArray [["id", VIOC_IW_NEXTID], ["site", _site], ["dir", _dir], ["side", _side], ["state", "go"],
		["mine", objNull], ["u", objNull], ["t0", time], ["tp", -1], ["done", false], ["amb", _amb], ["test", _test], ["uav", false]];
	VIOC_IW_NEXTID = VIOC_IW_NEXTID + 1;
