//--- [entrada]: el IED estalla
VIOC_IW_fnc_iedBoom = {
	params ["_e"];
	private _m = _e get "mine";
	if (isNull _m) exitWith {};
	_e set ["state", "boom"];
	triggerAmmo _m;
	[_m] spawn {
		params ["_m"];
		sleep 0.5;
		if (!isNull _m) then {_m setDamage 1}; //--- respaldo: los IED de control remoto tienen triggerWhenDestroyed = 1
	};
