//--- [entrada, vehiculos, con detonador] -> true si estallo. Mira cada 0.2 s, 25 s como mucho y solo mientras hay un
//--- vehiculo a < 150 m.
VIOC_IW_fnc_iedWatch = {
	params ["_e", "_vs", "_det"];
	private _m = _e get "mine";
	private _u = _e get "u";
	private _r = [VIOC_IW_IED_PRESS, VIOC_IW_IED_TRIG] select _det;
	private _t0 = time;
	private _tl = time;
	private _hitV = objNull;
	while {isNull _hitV && {!isNull _m} && {(time - _t0) < 25}} do {
		sleep 0.2;
		private _dt = ((time - _tl) max 0.2) min 2; _tl = time;  //--- el planificador estira el sleep: el radio crece con lo que avanza el vehiculo entre muestras
		if (_det && {!alive _u || {(lifeState _u) isEqualTo "INCAPACITATED"}}) then {_det = false; _r = VIOC_IW_IED_PRESS};
		{ if (alive _x && {(_x distance2D _m) < (_r max ((abs (speed _x)) / 3.6 * _dt * 0.5))}) exitWith {_hitV = _x} } forEach _vs;
		_vs = _vs select {alive _x && {(_x distance2D _m) < 150}};
		if (count _vs == 0) exitWith {};
	};
	if (isNull _hitV || {isNull _m}) exitWith {false};
	[_e] call VIOC_IW_fnc_iedBoom;
	true
};

//--- [entrada]: el plantador camina, se agacha, deja el IED, se va a su puesto de detonador y espera (40 min como mucho)
VIOC_IW_fnc_iedJob = {
	params ["_e"];
	private _site = _e get "site";
	private _dir = _e get "dir";
	private _side = _e get "side";
	private _test = _e get "test";
	private _sp = [_site, 150, 300, [250, 120] select _test, -1, 180, 16] call VIOC_IW_fnc_hiddenSpot;
	if (count _sp == 0) exitWith {
		_e set ["state", "sin lugar"];
		_e set ["done", true];
		[format ["IED %1: sin lugar oculto para el plantador", _e get "id"]] call VIOC_IW_fnc_log;
	};
	//--- el plantador: 60 % vestido de civil (bando civil, pistola escondida), 40 % guerrillero del bando
	private _u = objNull;
	private _covert = (random 1) < 0.6;
	if (!_covert) then {
		private _inf = [_side] call VIOC_IW_fnc_pool;
		if (count _inf > 0) then {
			private _g = createGroup [_side, true];
			if (!isNull _g) then {
				private _nu = [selectRandom _inf, _g, _sp, _side] call CTI_CO_FNC_CreateUnit;
				if (!isNil "_nu" && {_nu isEqualType objNull} && {!isNull _nu}) then {
					_u = _nu;
					_g allowFleeing 0;
					_g setBehaviour "AWARE";
					_g setCombatMode "YELLOW";
					_g setSpeedMode "NORMAL";
					_u setVariable ["vioc_iw_kind", "planter"];
					_u setVariable ["vioc_iw_side", _side];
					_u addEventHandler ["Hit", {
						params ["_hu", "_src"];
						_hu setVariable ["vioc_iw_hit", [time, _src]];
					}];
				};
			};
		};
	};
	if (isNull _u) then {_covert = true; _u = [call VIOC_IW_fnc_civClass, _sp, _side, "planter"] call VIOC_IW_fnc_mkCovert};
	if (isNull _u) exitWith {_e set ["state", "sin plantador"]; _e set ["done", true]};
