	while {_res == ""} do {
		sleep 0.25;
		if (!alive _v || {!(_v getVariable ["vioc_iw_armed", false])}) then {_res = ["desarmado", "destruido"] select (!alive _v)} else {
			if (!alive _d || {(lifeState _d) isEqualTo "INCAPACITATED"} || {!((vehicle _d) isEqualTo _v)}) then {_res = "sin conductor"; _v setVariable ["vioc_iw_armed", false]} else {  //--- PiR deja inconsciente en vez de matar
				_tp = [_e] call VIOC_IW_fnc_vbTargetPos;
				private _dist = _v distance2D _tp;
				_slow = if ((speed _v) < 3) then {_slow + 0.25} else {0};
				private _crowd = ((_v nearEntities [["CAManBase", "LandVehicle"], 10]) findIf {alive _x && {(side _x) in VIOC_IW_GOV}}) >= 0;
				if ((_dist < VIOC_IW_VB_BOOM) || {_crowd && {_dist < 60}} || {(_slow > 5) && {_dist < 50}}) then {[_v] call VIOC_IW_fnc_vbBoom; _res = "estallo"};
				if ((_res == "") && {(time - _t0) > 60}) then {_res = "atascado"; _v setVariable ["vioc_iw_armed", false]};
				if ((_res == "") && {(_cmd distance2D _tp) > 15}) then {_cmd = _tp; _d doMove _tp};
			};
		};
	};
	_res
};

//--- [entrada]: va despacio hacia el objetivo (10 min como mucho); en los ultimos 200 m, vbDash
VIOC_IW_fnc_vbJob = {
	params ["_e"];
	private _v = _e get "v";
	private _d = _e get "d";
	private _t0 = time;
	private _lp = getPosATL _v;
	private _lt = time;
	private _stuck = 0;
	private _res = "";
	while {_res == ""} do {
		sleep 2;
		if (missionNamespace getVariable ["CTI_GameOver", false]) then {_res = "fin de partida"};
		if ((_res == "") && {!alive _v || {!(_v getVariable ["vioc_iw_armed", false])}}) then {_res = ["desarmado", "destruido"] select (!alive _v)};
		if ((_res == "") && {!alive _d || {(lifeState _d) isEqualTo "INCAPACITATED"} || {!((vehicle _d) isEqualTo _v)}}) then {_res = "sin conductor"; _v setVariable ["vioc_iw_armed", false]};
		if (_res == "") then {
			private _tp = [_e] call VIOC_IW_fnc_vbTargetPos;
			if ((_v distance2D _lp) > 10) then {_lp = getPosATL _v; _lt = time};
			if ((time - _lt) > 40) then {_stuck = _stuck + 1; _lt = time; _d doMove _tp};
			if ((_stuck >= 3) || {(time - _t0) > 600}) then {_res = "atascado"; _v setVariable ["vioc_iw_armed", false]};
			if ((_res == "") && {(_v distance2D _tp) < VIOC_IW_VB_DASH}) then {_res = [_e] call VIOC_IW_fnc_vbDash};
		};
	};
	_e set ["state", _res];
	[format ["coche bomba hacia %1 (%2): %3", _e get "kind", mapGridPosition (_e get "tp"), _res]] call VIOC_IW_fnc_log;
	if (_res in ["estallo", "destruido"]) then {
		//--- el resto se borra a los 3 min sin jugadores a 100 m (como los restos de perf_cleanup) o a VIOC_IW_DEL_R
		[_v] spawn {
			params ["_w"];
			private _t = time;
			waitUntil {sleep 10; isNull _w || {((time - _t) > 180) && {!([_w, 100] call VIOC_IW_fnc_nearPlayer)}} || {missionNamespace getVariable ["CTI_GameOver", false]}};
			if (!isNull _w) then {deleteVehicle _w};
		};
		[[_d], 600] spawn VIOC_IW_fnc_retire;
	} else {
		if (alive _d && {(_d getVariable ["vioc_iw_revealed", -1]) >= 0}) then {[_d] call VIOC_IW_fnc_flee};  //--- conductor descubierto junto al objetivo: que no cuente para capturar el pueblo
		[[_v, _d], 600] spawn VIOC_IW_fnc_retire;
	};
	_e set ["done", true];
};

//--- [objetivo [posicion, tipo, peso, objeto o grupo], prueba] -> entrada (hashmap) o texto (por que no salio)
VIOC_IW_fnc_vbLaunch = {
	params ["_tg", ["_test", false]];
	_tg params ["_tp", "_kind", "", ["_tobj", objNull]];
	if (count VIOC_IW_VB_CARS == 0) exitWith {"no hay clases de coche civil"};
	if !([1] call VIOC_IW_fnc_room) exitWith {"sin presupuesto de IA"};
	//--- salida: un camino a 600-1100 m del objetivo, fuera de la vista, sin jugadores cerca, por tierra y lejos de la base
	private _sp = [];
	for "_i" from 1 to 16 do {
		if (count _sp == 0) then {
			private _q = _tp getPos [600 + random 500, random 360];
			private _r = [[_q select 0, _q select 1, 0], 150] call VIOC_IW_fnc_roadAt;
			if (count _r > 0) then {
				_r params ["_rp", "_rd"];
				if (!([_rp, [450, 350] select _test] call VIOC_IW_fnc_nearPlayer) && {!([_rp, [900, 600] select _test] call VIOC_IW_fnc_seen)}
					&& {([_rp] call VIOC_IW_fnc_baseDist) > VIOC_IW_VB_BASE} && {[_rp, _tp] call VIOC_IW_fnc_dry}) then {_sp = [_rp, _rd]};
			};
		};
	};
	if (count _sp == 0) exitWith {"sin salida oculta por carretera a 600-1100 m"};
	_sp params ["_rp", "_rd"];
	private _side = [_tp] call VIOC_IW_fnc_insSideAt;
	private _v = createVehicle [selectRandomWeighted VIOC_IW_VB_CARS, _rp, [], 0, "NONE"];
	if (isNull _v) exitWith {"createVehicle fallo"};
	private _hd = _rp getDir _tp;
	if ((abs (((_rd - _hd) + 540) % 360 - 180)) > 90) then {_rd = _rd + 180};
	_v setDir _rd;
	_v setVariable ["vioc_civ", true, true];   //--- no se guarda (gancho de civ_vehicles en Server_SaveToProfile.sqf)
	_v setVariable ["VIOC_KEEP", true];        //--- perf_cleanup no lo toca
	_v setVariable ["vioc_iw_vbied", true];
	_v setVariable ["vioc_iw_armed", true];
	private _d = [call VIOC_IW_fnc_civClass, _rp getPos [6, _rd + 90], _side, "vbied"] call VIOC_IW_fnc_mkCovert;
	if (isNull _d) exitWith {deleteVehicle _v; "sin conductor"};
	_d assignAsDriver _v;
	_d moveInDriver _v;
	_v setVariable ["vioc_iw_drv", _d];
	_d setVariable ["vioc_iw_car", _v];
	_v addEventHandler ["Killed", {
		params ["_kv"];
		[_kv] call VIOC_IW_fnc_vbBoom;
	}];
	_d addEventHandler ["Killed", {
		params ["_kd"];
		private _kv = _kd getVariable ["vioc_iw_car", objNull];
		if (!isNull _kv) then {_kv setVariable ["vioc_iw_armed", false]};
	}];
	private _w = (group _d) addWaypoint [_tp, 0];
	_w setWaypointType "MOVE";
	_w setWaypointCompletionRadius 5;
	private _e = createHashMapFromArray [["v", _v], ["d", _d], ["tp", _tp], ["kind", _kind], ["tobj", _tobj], ["side", _side],
		["t0", time], ["state", "en camino"], ["done", false], ["test", _test]];
	isNil {VIOC_IW_VB pushBack _e};
	[_e] spawn VIOC_IW_fnc_vbJob;
	[12] call VIOC_IW_fnc_stat;
	[format ["coche bomba (%1, %2) sale de %3 hacia %4 en %5 (a %6 m)", typeOf _v, _side, mapGridPosition _rp, _kind, mapGridPosition _tp, round (_rp distance2D _tp)]] call VIOC_IW_fnc_log;
	_e
};

//--- cada 30 s: un coche bomba nuevo si toca (modo, 20 min de partida, espera, uno a la vez)
VIOC_IW_fnc_vbManager = {
	isNil {VIOC_IW_VB = VIOC_IW_VB select {!(_x get "done")}};
	if ((VIOC_IW_VB_MODE <= 0) || {time < VIOC_IW_VB_FIRST} || {time < VIOC_IW_VB_NEXT} || {count VIOC_IW_VB > 0}) exitWith {};
	private _ts = call VIOC_IW_fnc_vbTargets;
	if (count _ts == 0) exitWith {VIOC_IW_VB_NEXT = time + 120};
	private _flat = [];
	{ _flat pushBack _forEachIndex; _flat pushBack (_x select 2) } forEach _ts;
	private _r = [_ts select (selectRandomWeighted _flat), false] call VIOC_IW_fnc_vbLaunch;
	if (_r isEqualType "") then {
		VIOC_IW_VB_NEXT = time + 120;
		[format ["coche bomba: no salio (%1)", _r]] call VIOC_IW_fnc_log;
	} else {
		VIOC_IW_VB_NEXT = time + (VIOC_IW_VB_GAP select VIOC_IW_VB_MODE) * (1 + random 0.5);
	};
};

//=====================================================================================================================
// Bucle
//=====================================================================================================================
VIOC_IW_fnc_mkRefresh = {
	{ deleteMarkerLocal _x } forEach VIOC_IW_MKS;
	VIOC_IW_MKS = [];
	if (!VIOC_IW_MARK || {!hasInterface}) exitWith {};
	private _mk = {
		params ["_p", "_type", "_col", "_txt"];
		private _m = createMarkerLocal [format ["vioc_iw_mk_%1", count VIOC_IW_MKS], _p];
		_m setMarkerTypeLocal _type;
		_m setMarkerColorLocal _col;
		_m setMarkerTextLocal _txt;
		VIOC_IW_MKS pushBack _m;
	};
	{ if (alive _x) then {[getPosATL _x, "mil_dot", ["ColorOrange", "ColorRed"] select ((_x getVariable ["vioc_iw_revealed", -1]) >= 0), _x getVariable ["vioc_iw_kind", "?"]] call _mk} } forEach VIOC_IW_SLEEPERS;
	{
		[_x get "site", "mil_destroy", "ColorRed", format ["IED %1 %2", _x get "id", _x get "state"]] call _mk;
		private _pu = _x get "u";
		if (!isNull _pu && {alive _pu}) then {[getPosATL _pu, "mil_dot", ["ColorRed", "ColorOrange"] select (_pu getVariable ["vioc_iw_covert", false]), format ["plantador IED %1", _x get "id"]] call _mk};
	} forEach VIOC_IW_IEDS;
	{ private _l = leader (_x get "g"); if (!isNull _l) then {[getPosATL _l, "mil_objective", "ColorRed", format ["emboscada %1", _x get "state"]] call _mk} } forEach VIOC_IW_AMB;
	{ private _v = _x get "v"; if (!isNull _v) then {[getPosATL _v, "mil_dot", "ColorBlack", format ["coche bomba %1", _x get "state"]] call _mk} } forEach VIOC_IW_VB;
	{ private _l = leader _x; if (!isNull _l) then {[getPosATL _l, "mil_dot", "ColorYellow", "atraido por un halcon"] call _mk} } forEach VIOC_IW_HUNT;
};

VIOC_IW_fnc_loop = {
	waitUntil {sleep 2; !isNil "CTI_InitTowns" && {!isNil "CTI_Towns"} && {!isNil "CTI_Init_Server"}};
	waitUntil {sleep 2; missionNamespace getVariable ["CTI_Server_Loaded", false]};
	waitUntil {sleep 2; ({isNil {_x getVariable "cti_town_sideID"}} count CTI_Towns) == 0};
	sleep 20;
	VIOC_IW_INS_IDS = VIOC_IW_INS apply {(_x) call CTI_CO_FNC_GetSideID};
	VIOC_IW_GOV_IDS = VIOC_IW_GOV apply {(_x) call CTI_CO_FNC_GetSideID};
	call VIOC_IW_fnc_townsTick;
	call VIOC_IW_fnc_bases;
	VIOC_IW_EKH = addMissionEventHandler ["EntityKilled", {_this call VIOC_IW_fnc_onKilled}];
	VIOC_IW_READY = true;
	[format ["activa en %1: insurgencia %2, gobierno %3; durmientes nivel %4, IED %5, emboscadas %6, coche bomba %7, castigo %8; pistolas %9, IED %10, coches %11, bomba %12, civiles de civ_people %13, ai_tactics %14",
		worldName, VIOC_IW_INS, VIOC_IW_GOV, VIOC_IW_SLEEP_LVL, VIOC_IW_IED_MAX, VIOC_IW_AMB_ON, VIOC_IW_VB_MODE, VIOC_IW_PENALTY, count VIOC_IW_PISTOLS,
		VIOC_IW_IED_LAND + VIOC_IW_IED_URBAN, (count VIOC_IW_VB_CARS) / 2, VIOC_IW_VB_AMMO, !isNil "VIOC_CIVP_ACTIVE", !isNil "VIOC_TAC_RUNNING"]] call VIOC_IW_fnc_log;
	private _n = 0;
	while {!(missionNamespace getVariable ["CTI_GameOver", false])} do {
		sleep VIOC_IW_PERIOD;
		_n = _n + 1;
		isNil {VIOC_IW_SLEEPERS = VIOC_IW_SLEEPERS select {alive _x}};
		{ [_x] call VIOC_IW_fnc_sleeperTick } forEach (VIOC_IW_SLEEPERS + []);
		if ((_n % 2) == 0) then {
			call VIOC_IW_fnc_townsTick;
			call VIOC_IW_fnc_sleeperSpawn;
			call VIOC_IW_fnc_huntTick;
			call VIOC_IW_fnc_iedManager;
		};
		if ((_n % 6) == 3) then {
			call VIOC_IW_fnc_civScan;
			call VIOC_IW_fnc_uavScan;
			call VIOC_IW_fnc_vbManager;
		};
		if ((_n % 12) == 0) then {call VIOC_IW_fnc_bases};
		if (VIOC_IW_MARK || {count VIOC_IW_MKS > 0}) then {call VIOC_IW_fnc_mkRefresh};
	};
	{ [_x] call VIOC_IW_fnc_huntRelease } forEach (VIOC_IW_HUNT + []);
};

