VIOC_IW_fnc_info = {
	private _nl = toString [10];
	private _sl = VIOC_IW_SLEEPERS select {alive _x};
	private _t = format ["VIOC guerra irregular: %1 (lobby %2, mision B %3, lista %4); insurgencia %5, gobierno %6", ["APAGADA", "ACTIVA"] select VIOC_IW_ON, VIOC_IW_MODE, VIOC_IW_MB, VIOC_IW_READY, VIOC_IW_INS, VIOC_IW_GOV];
	_t = _t + _nl + format ["Durmientes vivos %1 (halcones %2, descubiertos %3); nivel %4, tope %5", count _sl, {(_x getVariable ["vioc_iw_kind", ""]) == "hawk"} count _sl,
		{(_x getVariable ["vioc_iw_revealed", -1]) >= 0} count _sl, VIOC_IW_SLEEP_LVL, VIOC_IW_SL_TOTAL select VIOC_IW_SLEEP_LVL];
	_t = _t + _nl + format ["IED %1 / tope %2 (proximo en %3 s): %4", count VIOC_IW_IEDS, VIOC_IW_IED_MAX, round ((VIOC_IW_IED_NEXT max VIOC_IW_IED_START) - time) max 0,
		VIOC_IW_IEDS apply {[_x get "id", _x get "state", mapGridPosition (_x get "site")]}];
	_t = _t + _nl + format ["Emboscadas: %1", VIOC_IW_AMB apply {[_x get "state", {alive _x} count (units (_x get "g"))]}];
	_t = _t + _nl + format ["Coche bomba: %1 (proximo en %2 s)", VIOC_IW_VB apply {[_x get "state", _x get "kind", mapGridPosition (_x get "tp")]}, round (((VIOC_IW_VB_NEXT max VIOC_IW_VB_FIRST) - time) max 0)];
	_t = _t + _nl + format ["Grupos atraidos por halcones: %1", VIOC_IW_HUNT apply {groupId _x}];
	_t = _t + _nl + format ["Pueblos hostiles: %1", VIOC_IW_HOSTILE apply {[_x getVariable ["cti_town_name", "?"], (round (([_x] call VIOC_IW_fnc_host) * 100)) / 100]}];
	_t = _t + _nl + format ["INFO %1", VIOC_IW_INFO];
	if (hasInterface) then {copyToClipboard _t};
	_t
};

VIOC_IW_fnc_markers = {
	VIOC_IW_MARK = !VIOC_IW_MARK;
	call VIOC_IW_fnc_mkRefresh;
	format ["marcadores de guerra irregular: %1 (se actualizan cada 5 s)", ["apagados", "encendidos"] select VIOC_IW_MARK]
};

//--- [jugador] -> [lugar, rumbo] en un camino a 300-550 m delante del jugador, o []
VIOC_IW_fnc_roadAhead = {
	params ["_pl"];
	private _res = [];
	{
		if (count _res == 0) then {
			private _q = _pl getPos [_x, getDir _pl];
			private _r = [[_q select 0, _q select 1, 0], 150] call VIOC_IW_fnc_roadAt;
			if ((count _r > 0) && {((_r select 0) distance2D _pl) > 250}) then {
				_r params ["_rp", "_dir", "_wd"];
				private _s = _rp getPos [(((_wd / 2) - 0.5) max 1), _dir + 90];
				_res = [[_s select 0, _s select 1, 0], _dir];
			};
		};
	} forEach [400, 300, 500, 550];
	_res
};

VIOC_IW_fnc_testSleeper = {
	params [["_pl", objNull], ["_hawk", false]];
	if (!VIOC_IW_ON || {!VIOC_IW_READY}) exitWith {"guerra irregular apagada (VIOC_IRREG) o todavia arrancando"};
	if (isNull _pl) exitWith {"sin jugador"};
	private _p = _pl getPos [35, (getDir _pl) + 180];
	private _u = [call VIOC_IW_fnc_civClass, [_p select 0, _p select 1, 0], VIOC_IW_INS select 0, ["sleeper", "hawk"] select _hawk, [_p, 700] call VIOC_IW_fnc_nearTown] call VIOC_IW_fnc_mkCovert;
	if (isNull _u) exitWith {"no se pudo crear"};
	_u setVariable ["vioc_iw_t0", time - 15];
	isNil {VIOC_IW_SLEEPERS pushBack _u};
	[0] call VIOC_IW_fnc_stat;
	format ["%1 de prueba (%2, pistola %3 escondida) a 35 m detras de ti. %4", ["Durmiente", "Halcon"] select _hawk, VIOC_IW_INS select 0, _u getVariable ["vioc_iw_pistol", "-"],
		["Acercate a 25 m o menos (con 4 soldados o menos a 60 m): se descubre y dispara.", "Te sigue a 50-150 m y avisa a los insurgentes a 1.5 km cada 30 s mientras te ve."] select _hawk]
};

VIOC_IW_fnc_testIED = {
	params [["_pl", objNull], ["_amb", false]];
	if (!VIOC_IW_ON || {!VIOC_IW_READY}) exitWith {"guerra irregular apagada (VIOC_IRREG) o todavia arrancando"};
	if (isNull _pl) exitWith {"sin jugador"};
	private _r = [_pl] call VIOC_IW_fnc_roadAhead;
	if (count _r == 0) exitWith {"no hay camino a 300-550 m delante de ti (mira hacia una carretera)"};
	_r params ["_site", "_dir"];
	private _e = [_site, _dir, [_site] call VIOC_IW_fnc_insSideAt, true, _amb] call VIOC_IW_fnc_iedLaunch;
	format ["IED de prueba %1 en %2 (a %3 m)%4. El plantador sale a 150-300 m del camino; call VIOC_IW_fnc_markers para verlo.", _e get "id", mapGridPosition _site,
		round (_pl distance2D _site), ["", " con emboscada"] select _amb]
};

VIOC_IW_fnc_testAmbush = {
	params [["_pl", objNull]];
	if (!VIOC_IW_ON || {!VIOC_IW_READY}) exitWith {"guerra irregular apagada (VIOC_IRREG) o todavia arrancando"};
	if (isNull _pl) exitWith {"sin jugador"};
	if (count VIOC_IW_AMB >= VIOC_IW_AMB_MAX) exitWith {"ya hay 2 emboscadas"};
	private _r = [_pl] call VIOC_IW_fnc_roadAhead;
	if (count _r == 0) exitWith {"no hay camino a 300-550 m delante de ti (mira hacia una carretera)"};
	_r params ["_site", "_dir"];
	private _e = createHashMapFromArray [["id", VIOC_IW_NEXTID], ["site", _site], ["dir", _dir], ["side", [_site] call VIOC_IW_fnc_insSideAt], ["state", "sin IED"],
		["mine", objNull], ["u", objNull], ["t0", time], ["tp", -1], ["done", false], ["amb", true], ["test", true], ["uav", false]];
	VIOC_IW_NEXTID = VIOC_IW_NEXTID + 1;
	[_e] spawn VIOC_IW_fnc_ambushJob;
	format ["Emboscada de prueba junto al camino en %1 (a %2 m): ataca si el gobierno pasa a 80 m del camino, a 50 m de ellos o si los ven.", mapGridPosition _site, round (_pl distance2D _site)]
};

VIOC_IW_fnc_testVBIED = {
	params [["_pl", objNull]];
	if (!VIOC_IW_ON || {!VIOC_IW_READY}) exitWith {"guerra irregular apagada (VIOC_IRREG) o todavia arrancando"};
	if (isNull _pl) exitWith {"sin jugador"};
	if (count VIOC_IW_VB > 0) exitWith {"ya hay un coche bomba en marcha"};
	private _r = [[(getPosATL _pl) call VIOC_IW_fnc_p0, "jugador (prueba)", 1, _pl], true] call VIOC_IW_fnc_vbLaunch;
	if (_r isEqualType "") exitWith {"no salio: " + _r};
	format ["Coche bomba de prueba (%1) sale de %2 hacia ti (a %3 m). A 200 m se descubre y acelera; dispara al coche (explota alli) o al conductor (no explota).",
		typeOf (_r get "v"), mapGridPosition (_r get "v"), round ((_r get "v") distance2D _pl)]
};

if (VIOC_IW_ON) then {
	[] spawn VIOC_IW_fnc_loop;
} else {
	diag_log format ["[VIOC irregular] apagada (VIOC_IRREG = %1, mision B %2)", VIOC_IW_MODE, VIOC_IW_MB];
};

